CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),username VARCHAR(24) UNIQUE NOT NULL,email VARCHAR(254) UNIQUE,password_hash TEXT NOT NULL,display_name VARCHAR(40) NOT NULL,bio VARCHAR(500) DEFAULT '',avatar_url TEXT,role VARCHAR(16) DEFAULT 'user',rank VARCHAR(24) DEFAULT 'FREE',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_id UUID REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(100) NOT NULL,description TEXT DEFAULT '',content JSONB DEFAULT '{}'::jsonb,visibility VARCHAR(12) DEFAULT 'private',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS levels(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_id UUID REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(100) NOT NULL,description TEXT DEFAULT '',data JSONB DEFAULT '{}'::jsonb,thumbnail_url TEXT,visibility VARCHAR(12) DEFAULT 'private',published BOOLEAN DEFAULT false,plays BIGINT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS worlds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_id UUID REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,description TEXT DEFAULT '',settings JSONB DEFAULT '{}'::jsonb,visibility VARCHAR(12) DEFAULT 'private',created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS assets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_id UUID REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(120) NOT NULL,mime_type VARCHAR(100),url TEXT NOT NULL,size_bytes BIGINT DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS entitlements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,code VARCHAR(64) NOT NULL,source VARCHAR(32) DEFAULT 'admin',expires_at TIMESTAMPTZ,UNIQUE(user_id,code));
CREATE TABLE IF NOT EXISTS credit_ledger(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,amount BIGINT NOT NULL,reason TEXT,provider VARCHAR(32),provider_reference VARCHAR(160),created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(provider,provider_reference));
CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_id UUID REFERENCES users(id) ON DELETE SET NULL,action TEXT NOT NULL,target_type TEXT,target_id TEXT,metadata JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT NOW());
